//! Register behaviour against the pinned Ruby reference
//! (`fixtures/register/reference.json`, regenerated by
//! `fixtures/register/capture-reference.rb`).
//!
//! Scratch directories are created fresh by each test under the system temp
//! directory and removed only by the test that created them. No network is
//! used: clone/update run against synthetic local git repositories.

use serde_json::{json, Value as Json};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};
use ukiryu::register::{self, DiscoveryContext, Error, Git, Register, Source, VersionFile};
use yeptris::{Number, Value as Yaml};

fn manifest_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .to_path_buf()
}

fn fixture() -> PathBuf {
    manifest_root().join("fixtures/register/spec")
}

fn reference() -> Json {
    let text =
        fs::read_to_string(manifest_root().join("fixtures/register/reference.json")).unwrap();
    serde_json::from_str(&text).unwrap()
}

/// A fresh scratch directory owned (and removed) by one test.
struct Scratch(PathBuf);

impl Scratch {
    fn new(label: &str) -> Scratch {
        static COUNTER: AtomicUsize = AtomicUsize::new(0);
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!(
            "ukiryu-register-{label}-{}-{}-{nanos}",
            std::process::id(),
            COUNTER.fetch_add(1, Ordering::SeqCst)
        ));
        fs::create_dir(&dir).expect("scratch directory must be new");
        Scratch(dir)
    }
    fn path(&self, rel: &str) -> PathBuf {
        self.0.join(rel)
    }
    fn write(&self, rel: &str, content: &str) -> PathBuf {
        let path = self.path(rel);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, content).unwrap();
        path
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn slash(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn tokenize(path: &Path, prefix: &Path, token: &str) -> String {
    let path = slash(path);
    let prefix = slash(prefix);
    match path.strip_prefix(&prefix) {
        Some(rest) => format!("{token}{rest}"),
        None => path,
    }
}

fn typed(value: &Yaml) -> Json {
    match value {
        Yaml::Null => Json::Null,
        Yaml::String(s) => json!({"type":"string","value":s}),
        Yaml::Number(Number::F64(n)) => json!({"type":"float","value":register::ruby_float(*n)}),
        Yaml::Number(Number::I64(n)) => json!({"type":"integer","value":n.to_string()}),
        Yaml::Number(Number::U64(n)) => json!({"type":"integer","value":n.to_string()}),
        Yaml::Bool(b) => json!({"type":"boolean","value":b}),
        other => json!({"type":"other","value":format!("{other:?}")}),
    }
}

fn versions_json(versions: &[VersionFile], prefix: &Path, token: &str) -> Json {
    Json::Array(
        versions
            .iter()
            .map(|v| json!([tokenize(&v.path, prefix, token), typed(&v.equals)]))
            .collect(),
    )
}

#[test]
fn fixture_corpus_matches_reference() {
    let expected = &reference()["fixture"];
    let root = fixture();
    let reg = Register::at(&root);
    assert_eq!(reg.source().as_str(), expected["source"]);
    assert_eq!(json!(reg.exists()), expected["exists"]);
    assert_eq!(json!(reg.valid()), expected["valid"]);
    let names = reg.tool_names();
    assert_eq!(json!(names), expected["tool_names"]);

    for (name, want) in expected["tool?"].as_object().unwrap() {
        assert_eq!(json!(reg.has_tool(name)), *want, "tool? {name}");
    }
    for (name, want) in expected["list_versions"].as_object().unwrap() {
        let got = versions_json(&reg.list_versions(name).unwrap(), &root, "<FIXTURE>");
        assert_eq!(got, *want, "list_versions {name}");
    }
    for (name, queries) in expected["load_tool_yaml"].as_object().unwrap() {
        let versions = reg.list_versions(name).unwrap();
        for (query, want) in queries.as_object().unwrap() {
            let version = (query != "<latest>").then_some(query.as_str());
            let got = reg.load_tool_yaml(name, version).unwrap().map(|content| {
                versions
                    .iter()
                    .find(|v| fs::read_to_string(&v.path).unwrap() == content)
                    .map_or("<other>".to_owned(), |v| {
                        tokenize(&v.path, &root, "<FIXTURE>")
                    })
            });
            assert_eq!(json!(got), *want, "load_tool_yaml {name} {query}");
        }
    }
}

/// Typed loads go through the generic serde entrypoint. Until the shared
/// models land these assertions use the YAML tree; the model-level
/// comparison (`interface_version` default, symbol-valued fields) is pending
/// integration with the model owner's types.
#[test]
fn typed_loads_reach_every_fixture_family() {
    let expected = &reference()["fixture"];
    let reg = Register::at(fixture());
    let text = |v: &Yaml, key: &str| match v {
        Yaml::Mapping(m) => m
            .get(&Yaml::String(key.into()))
            .cloned()
            .unwrap_or(Yaml::Null),
        _ => Yaml::Null,
    };
    for (name, want) in expected["implementation_index"].as_object().unwrap() {
        let got: Option<Yaml> = reg.load_implementation_index(name).unwrap();
        assert_eq!(got.is_some(), !want.is_null(), "index {name}");
        if let Some(index) = got {
            assert_eq!(
                typed(&text(&index, "name")),
                want["name"],
                "index name {name}"
            );
            assert_eq!(typed(&text(&index, "interface")), want["interface"]);
        }
    }
    for (name, want) in expected["interface"].as_object().unwrap() {
        let got: Option<Yaml> = reg.load_interface(name).unwrap();
        assert_eq!(got.is_some(), !want.is_null(), "interface {name}");
        if let Some(interface) = got {
            assert_eq!(
                typed(&text(&interface, "name")),
                want["name"],
                "interface {name}"
            );
            assert_eq!(typed(&text(&interface, "version")), want["version"]);
        }
    }
    for case in expected["implementation_version"].as_array().unwrap() {
        let got: Option<Yaml> = reg
            .load_implementation_version(
                case["tool"].as_str().unwrap(),
                case["implementation"].as_str().unwrap(),
                case["file"].as_str().unwrap(),
            )
            .unwrap();
        let want = &case["loaded"];
        assert_eq!(got.is_some(), !want.is_null(), "{case}");
        if let Some(version) = got {
            assert_eq!(typed(&text(&version, "version")), want["version"], "{case}");
            assert_eq!(
                typed(&text(&version, "implements")),
                want["implements"],
                "{case}"
            );
        }
    }
    let missing: Option<Yaml> = reg
        .load_implementation_version("gzip", "default", "missing.yaml")
        .unwrap();
    assert!(missing.is_none());
    assert!(expected["implementation_version_missing"].is_null());
}

fn build_layout(scratch: &Scratch, name: &str) -> PathBuf {
    let dir = scratch.path(&format!("layout/{name}"));
    let files: &[(&str, Option<&str>)] = match name {
        "missing" => return dir,
        "file_not_dir" => {
            fs::create_dir_all(dir.parent().unwrap()).unwrap();
            fs::write(&dir, "not a directory").unwrap();
            return dir;
        }
        "empty" => &[],
        "tools_empty" => &[("tools", None)],
        "tool_dir_no_yaml" => &[("tools/demo/readme.txt", Some("x"))],
        "top_level_yaml_only" => &[("tools/demo.yaml", Some("name: demo"))],
        "nested_too_deep" => &[("tools/demo/default/1.0.yaml", Some("version: \"1.0\""))],
        "index_only" => &[(
            "tools/demo/index.yaml",
            Some("name: demo\ninterface: demo\nimplementations: []\n"),
        )],
        "other_yaml_only" => &[("tools/demo/1.0.yaml", Some("name: demo"))],
        other => panic!("unknown layout {other}"),
    };
    fs::create_dir_all(&dir).unwrap();
    for (rel, content) in files {
        let path = dir.join(rel);
        match content {
            None => fs::create_dir_all(&path).unwrap(),
            Some(c) => {
                fs::create_dir_all(path.parent().unwrap()).unwrap();
                fs::write(&path, c).unwrap();
            }
        }
    }
    dir
}

#[test]
fn structure_validity_matches_reference() {
    let scratch = Scratch::new("structure");
    for (name, want) in reference()["structure"].as_object().unwrap() {
        let reg = Register::at(build_layout(&scratch, name));
        assert_eq!(json!(reg.exists()), want["exists"], "{name}");
        assert_eq!(json!(reg.valid()), want["valid"], "{name}");
        assert_eq!(
            json!({"ok": reg.tool_names()}),
            want["tool_names"],
            "{name}"
        );
    }
}

const DUP_INDEX: &str = "name: dup
interface: dup
implementations:
- name: zeta
  versions:
  - equals: '2.0'
    file: 2.0.yaml
  - equals: 1.5
    file: 1.5.yaml
  - equals: 3
    file: 3.yaml
  - after: '4.0'
    file: 4.yaml
  - equals: '2.0-again'
    file: 2.0.yaml
  - file: nofile-equals.yaml
  - equals: '9'
- name: alpha
  versions:
  - equals: '1.0'
    file: 1.0.yaml
- name: noversions
- name: zeta
  versions:
  - equals: 'z2'
    file: 2.0.yaml
";

#[test]
fn ordering_duplicates_and_value_types_match_reference() {
    let expected = &reference()["ordering"];
    let scratch = Scratch::new("ordering");
    let dup = scratch.path("dup");
    scratch.write("dup/tools/dup/index.yaml", DUP_INDEX);
    for f in [
        "zeta/2.0.yaml",
        "zeta/1.5.yaml",
        "zeta/3.yaml",
        "zeta/4.yaml",
        "alpha/1.0.yaml",
    ] {
        scratch.write(&format!("dup/tools/dup/{f}"), &format!("file: {f}\n"));
    }
    scratch.write("dup/tools/dup/1.5.yaml", "file: top-level 1.5\n");
    scratch.write("dup/tools/empty/index.yaml", "");
    scratch.write("dup/tools/nullidx/index.yaml", "--- ~\n");
    scratch.write(
        "dup/tools/noimpls/index.yaml",
        "name: noimpls\ninterface: x\n",
    );
    scratch.write(
        "dup/interfaces/nested/x/1.0.yaml",
        "name: nested\nversion: '1.0'\nactions: {}\n",
    );
    scratch.write("dup/interfaces/empty.yaml", "");
    let reg = Register::at(&dup);
    let tmp = &scratch.0;

    assert_eq!(json!(reg.tool_names()), expected["tool_names"]);
    for (name, want) in expected["list_versions"].as_object().unwrap() {
        let got = versions_json(&reg.list_versions(name).unwrap(), tmp, "<TMP>");
        assert_eq!(json!({"ok": got}), *want, "list_versions {name}");
    }
    for (query, want) in expected["load_tool_yaml"].as_object().unwrap() {
        let version = (query != "<latest>").then_some(query.as_str());
        let got = reg.load_tool_yaml("dup", version).unwrap();
        assert_eq!(json!({"ok": got}), *want, "load_tool_yaml {query}");
    }
    assert_eq!(
        json!({"ok": reg.load_tool_yaml("empty", None).unwrap()}),
        expected["load_tool_yaml_empty"]
    );
    let nested: Option<Yaml> = reg.load_interface("nested/x/1.0").unwrap();
    let nested_name = match nested.unwrap() {
        Yaml::Mapping(m) => m.get(&Yaml::String("name".into())).cloned().unwrap(),
        other => panic!("{other:?}"),
    };
    assert_eq!(
        json!({"ok": typed(&nested_name)}),
        expected["interface_nested"]
    );
    let empty: Option<Yaml> = reg.load_interface("empty").unwrap();
    assert_eq!(
        json!({"ok": empty.map(|_| ())}),
        expected["interface_empty"]
    );
    let empty: Option<Yaml> = reg.load_implementation_index("empty").unwrap();
    assert_eq!(json!({"ok": empty.map(|_| ())}), expected["index_empty"]);
    let nullidx: Option<Yaml> = reg.load_implementation_index("nullidx").unwrap();
    assert_eq!(json!({"ok": nullidx.map(|_| ())}), expected["index_null"]);
}

#[test]
fn discovery_chain_matches_reference() {
    let scratch = Scratch::new("discovery");
    let tmp = scratch.0.clone();
    scratch.write("valid/tools/demo/index.yaml", "name: demo\n");
    fs::create_dir_all(scratch.path("invalid")).unwrap();
    scratch.write(
        "home-valid/.ukiryu/register/tools/demo/index.yaml",
        "name: demo\n",
    );
    fs::create_dir_all(scratch.path("home-invalid/.ukiryu/register")).unwrap();
    fs::create_dir_all(scratch.path("home-empty")).unwrap();
    scratch.write("dev-file", "a file, not a directory");
    let path_for = |key: &str| -> Option<PathBuf> {
        match key {
            "none" => None,
            "empty_string" => Some(PathBuf::new()),
            "file" => Some(scratch.path("dev-file")),
            other => Some(scratch.path(other)),
        }
    };
    let cases = reference()["discovery"].as_array().unwrap().clone();
    assert_eq!(cases.len(), 6 * 5 * 3);
    for case in cases {
        let ctx = DiscoveryContext {
            env_register: path_for(case["env"].as_str().unwrap()).map(Into::into),
            dev_path: path_for(case["dev"].as_str().unwrap()),
            home: Some(scratch.path(&format!("home-{}", case["home"].as_str().unwrap()))),
        };
        let (path, source) = ctx.discover_path().unwrap();
        assert_eq!(
            json!([tokenize(&path, &tmp, "<TMP>"), source.as_str()]),
            case["discover_path"],
            "{case}"
        );
        let resolved = ctx.resolve_path_without_clone();
        assert_eq!(
            json!(resolved.map(|p| tokenize(&p, &tmp, "<TMP>"))),
            case["resolve_path_without_clone"],
            "{case}"
        );
        // Divergence: the source returns nil (not false) when nothing resolves.
        let want_exists = case["exists?"]["value"].as_bool().unwrap_or(false);
        assert_eq!(ctx.exists(), want_exists, "{case}");
    }
}

#[test]
fn discovery_without_home_reports_not_found() {
    let ctx = DiscoveryContext::default();
    assert_eq!(ctx.discover_path(), None);
    let err = ctx.discover(&Git::default()).unwrap_err();
    assert_eq!(err.class_name(), "Ukiryu::Register::NotFoundError");
    assert_eq!(err.to_string(), "No register found and auto-clone failed");
}

fn git(dir: &Path, args: &[&str]) {
    let status = Command::new("git")
        .args([
            "-c",
            "user.name=Ukiryu Fixture",
            "-c",
            "user.email=fixture@example.invalid",
            "-c",
            "init.defaultBranch=main",
            "-c",
            "commit.gpgsign=false",
        ])
        .args(args)
        .current_dir(dir)
        .status()
        .expect("installed git is required for clone/update tests");
    assert!(status.success(), "git {args:?}");
}

fn upstream(scratch: &Scratch, name: &str, file: &str) -> PathBuf {
    let dir = scratch.path(name);
    scratch.write(&format!("{name}/{file}"), "name: demo\n");
    git(&dir, &["init", "-q"]);
    git(&dir, &["add", "."]);
    git(&dir, &["commit", "-q", "-m", "initial"]);
    dir
}

fn error_view(err: &Error, scratch: &Scratch, upstream: &Path, token: &str) -> Json {
    let message = slash(Path::new(&err.to_string()))
        .replace(&slash(upstream), token)
        .replace(&slash(&scratch.0), "<TMP>");
    let lines: Vec<&str> = message.split_inclusive('\n').collect();
    let first = lines.first().map_or("", |l| l.trim_end_matches('\n'));
    let tail: String = lines
        .iter()
        .skip_while(|l| !l.starts_with("To fix this:") && !l.starts_with("This error usually"))
        .copied()
        .collect();
    json!({"class": err.class_name(), "first_line": first, "ukiryu_tail": tail})
}

fn assert_error(got: Json, want: &Json, label: &str) {
    let want = &want["error"];
    assert_eq!(got["class"], want["class"], "{label}");
    assert_eq!(got["ukiryu_tail"], want["ukiryu_tail"], "{label}");
    let first = got["first_line"].as_str().unwrap();
    let want_first = want["first_line"].as_str().unwrap();
    // The git layer's own failure text differs between the git gem and the
    // installed-git port; the Ukiryu framing before it must match exactly.
    if want_first.starts_with("Failed to clone register") {
        assert!(
            first.starts_with(want_first),
            "{label}: {first:?} vs {want_first:?}"
        );
    } else {
        assert_eq!(first, want_first, "{label}");
    }
}

#[test]
fn clone_and_update_match_reference() {
    let expected = &reference()["clone"];
    let scratch = Scratch::new("clone");
    let up = upstream(&scratch, "upstream", "tools/demo/index.yaml");
    let empty_up = upstream(&scratch, "empty-upstream", "README");
    let git_for = |remote: &Path| Git {
        program: "git".into(),
        remote_url: slash(remote),
    };
    let g = git_for(&up);

    let fresh = Register::at(scratch.path("clones/fresh/register"));
    fresh.clone_register(&g).unwrap();
    assert!(expected["fresh"]["ok"].is_null());
    let after = &expected["fresh_after"];
    assert_eq!(json!(fresh.exists()), after["exists"]);
    assert_eq!(json!(fresh.valid()), after["valid"]);
    assert_eq!(json!(fresh.tool_names()), after["tool_names"]);

    let again = fresh.clone_register(&g).unwrap_err();
    assert_error(
        error_view(&again, &scratch, &up, "<UPSTREAM>"),
        &expected["again"],
        "again",
    );
    fresh.ensure_exists(&g).unwrap();

    git(&up, &["mv", "tools/demo", "tools/demo2"]);
    git(&up, &["commit", "-q", "-m", "rename"]);
    fresh.update(&g).unwrap();
    assert_eq!(json!(fresh.tool_names()), expected["update_after"]);

    let via_update = Register::at(scratch.path("clones/via-update/register"));
    via_update.update(&g).unwrap();
    assert_eq!(
        json!({"ok": via_update.tool_names()}),
        expected["update_missing_clones"]
    );

    let not_git = scratch.path("clones/not-git");
    scratch.write("clones/not-git/tools/demo/index.yaml", "name: demo\n");
    let err = Register::at(&not_git).update(&g).unwrap_err();
    assert_error(
        error_view(&err, &scratch, &up, "<UPSTREAM>"),
        &expected["update_not_git"],
        "update_not_git",
    );
    assert!(not_git.join("tools/demo/index.yaml").exists());

    // Source hazard: Ruby deletes this pre-existing directory. The port keeps it.
    let occupied = scratch.path("clones/occupied");
    scratch.write("clones/occupied/user-work.txt", "precious\n");
    let err = Register::at(&occupied).ensure_exists(&g).unwrap_err();
    assert_error(
        error_view(&err, &scratch, &up, "<UPSTREAM>"),
        &expected["ensure_exists_occupied"],
        "occupied",
    );
    assert_eq!(
        expected["occupied_survives"],
        json!(false),
        "reference records the source hazard"
    );
    assert!(
        occupied.join("user-work.txt").exists(),
        "port must not delete user work"
    );

    let missing_remote = scratch.path("no-such-upstream");
    let bad = Register::at(scratch.path("clones/bad/register"));
    let err = bad.clone_register(&git_for(&missing_remote)).unwrap_err();
    assert_error(
        error_view(&err, &scratch, &missing_remote, &slash(&missing_remote)),
        &expected["bad_remote"],
        "bad_remote",
    );
    assert_eq!(
        json!(bad.path().exists()),
        expected["bad_remote_path_exists"]
    );
    assert_eq!(
        json!(bad.path().parent().unwrap().exists()),
        expected["bad_remote_parent_exists"]
    );

    let no_tools = Register::at(scratch.path("clones/no-tools/register"));
    let err = no_tools.clone_register(&git_for(&empty_up)).unwrap_err();
    assert_error(
        error_view(&err, &scratch, &empty_up, "<EMPTY_UPSTREAM>"),
        &expected["no_tools"],
        "no_tools",
    );
    assert_eq!(
        json!(no_tools.path().exists()),
        expected["no_tools_path_exists"]
    );

    let info = fresh.info(&g);
    assert_eq!(info.source, Source::Manual);
    assert_eq!(info.tools_count, 1);
    let git_info = info.git_info.unwrap();
    assert_eq!(git_info.branch.as_deref(), Some("main"));
    assert_eq!(git_info.commit.unwrap().len(), 8);
}

#[test]
fn missing_git_executable_uses_path_guidance() {
    let scratch = Scratch::new("nogit");
    let reg = Register::at(scratch.path("register"));
    let git = Git {
        program: scratch.path("definitely-not-git"),
        remote_url: "https://example.invalid/register".into(),
    };
    let err = reg.clone_register(&git).unwrap_err();
    assert_eq!(err.class_name(), "Ukiryu::Register::CloneError");
    let message = err.to_string();
    assert!(
        message.starts_with("Failed to clone register: "),
        "{message}"
    );
    assert!(message.contains("This error usually means git is not in PATH"));
}
